#include <stdio.h>
#define CHANNELS 3
int main(void) {
    printf("%d\n",CHANNELS+1);
    return 0;
}

#include <stdio.h>
#define STEP (1 + 2)
int main(void) {
    printf("%d\n",2*STEP);
    return 0;
}

#include <stdio.h>
#define TWICE(x) ((x)+(x))
int main(void) {
    int sample=4;printf("%d\n",TWICE(sample+1));
    return 0;
}

#include <stdio.h>
static int twice(int value){return value+value;}
int main(void) {
    int i=3;int value=twice(i);++i;printf("%d %d\n",value,i);
    return 0;
}

#include <stdio.h>
