#if TRACE
#define LABEL "Отладка"
#else
#define LABEL "Работа"
#endif
int main(void) {
    puts(LABEL);
    return 0;
}

#include <stdio.h>
static int count(void){static int value=10;return ++value;}
int main(void) {
    int first=count();int second=count();printf("%d %d\n",first,second);
    return 0;
}

#include <stdio.h>
extern int limit;
int limit=8;
int main(void) {
    printf("%d\n",limit);
    return 0;
}

#include <stdio.h>
static int local_value(void){return 6;}
int main(void) {
    printf("%d\n",local_value());
    return 0;
}

#include <stdio.h>

int main(void) {
    int sample=5;const int *view=&sample;sample=6;printf("%d\n",*view);
    return 0;
}

#include <stdio.h>

int main(void) {
    volatile unsigned status=2;unsigned snapshot=status;status=4;printf("%u %u\n",snapshot,status);
    return 0;
}

#include <stdio.h>
static int negate(int x){return -x;}
int main(void) {
    int (*operation)(int)=negate;printf("%d\n",operation(7));
    return 0;
}

#include <stdio.h>
static void visit(int value,void *context){int *sum=context;*sum+=value;}
int main(void) {
    int sum=0;visit(4,&sum);visit(6,&sum);printf("%d\n",sum);
    return 0;
}

#include <stdio.h>

int main(void) {
    int value=9;void *opaque=&value;int *restored=opaque;printf("%d\n",*restored);
    return 0;
}

#include <stdio.h>

int main(void) {
    printf("%u\n",14u & 3u);
    return 0;
}

#include <stdio.h>

int main(void) {
    printf("%u\n",8u | 1u);
    return 0;
}

#include <stdio.h>

int main(void) {
    printf("%u\n",9u ^ 1u);
    return 0;
}

#include <stdio.h>

int main(void) {
    printf("%u\n",32u >> 2);
    return 0;
}

#include <stdio.h>

int main(void) {
    unsigned packet=28;printf("%u\n",(packet >> 2) & 7u);
    return 0;
}

#include <stdio.h>

int main(void) {
    unsigned pending=7;unsigned acknowledge=1;printf("%u\n",pending & ~acknowledge);
    return 0;
}

#include <stdio.h>

int main(void) {
    unsigned value=258;printf("%u %u\n",value & 255u,(value >> 8) & 255u);
    return 0;
}

#include <stdio.h>

int main(void) {
    FILE *f=tmpfile();if(!f)return 1;if(fputs("AB",f)==EOF || fseek(f,0,SEEK_SET)!=0){fclose(f);return 1;}int c=fgetc(f);if(fclose(f)!=0 || c==EOF)return 1;printf("%c\n",c);
    return 0;
}

#include <stdio.h>

int main(void) {
    FILE *f=tmpfile();if(!f)return 1;unsigned char data[2]={3,4},copy[2];if(fwrite(data,1,2,f)!=2 || fseek(f,0,SEEK_SET)!=0 || fread(copy,1,2,f)!=2){fclose(f);return 1;}if(fclose(f)!=0)return 1;printf("%u %u\n",(unsigned)copy[0],(unsigned)copy[1]);
    return 0;
}

#include <stdio.h>
static int read_value(int valid,int *out){if(!valid)return 0;*out=42;return 1;}
int main(void) {
    int value=7;int ok=read_value(0,&value);printf("%d %d\n",ok,value);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
int main(void) {
    char *end;errno=0;long value=strtol("12x",&end,10);printf("%ld %c\n",value,*end);
    return 0;
}

#include <stdio.h>
#include <assert.h>
int main(void) {
    int count=3;assert(count>=0);printf("%d\n",count);
    return 0;
}
